"""Exact-context descriptive fits to released observations, never a calibrated twin.

The exported module is standalone and contains no source prior or simulator. A
specimen forecast deliberately has ``sd=None``: observed repeat scatter is not
an estimated future-delivery predictive distribution. See docs/FITTED_MODELS.md.
"""

import math
from collections import Counter, defaultdict

MODEL_VERSION = "released-exact-context-v1"
UNITS = {
    "density_g_cm3": "g/cm^3",
    "grain_size_nm": "nm",
    "grain_d90_nm": "nm",
    "coarse_number_fraction": "1",
    "porosity_area_fraction": "1",
}
GRAIN_QUANTITIES = {"grain_size_nm", "grain_d90_nm", "coarse_number_fraction"}
CONTEXT = (
    "lot_id",
    "route",
    "process_stage",
    "die_material",
    "pressure_mpa",
    "heating_rate_c_min",
    "hold_time_s",
    "post_treatment",
    "mass_g",
    "diameter_mm",
)
NUMERIC_CONTEXT = {"pressure_mpa", "heating_rate_c_min", "hold_time_s", "mass_g", "diameter_mm"}
MEASUREMENT_CONTEXT = ("method", "measurement_population", "measurement_statistic")


def _number(value):
    return not isinstance(value, bool) and isinstance(value, (int, float)) and math.isfinite(value)


def _known(value):
    return value is not None and value != ""


def _attestation_error(actual):
    """Validate optional operator provenance; never fill an absent actual value."""
    attestations = actual.get("attestations", {})
    if not isinstance(attestations, dict):
        return "Delivered attestations must map actual field names to provenance objects"
    for field, record in attestations.items():
        if (
            not isinstance(field, str)
            or field == "attestations"
            or field not in actual
            or not _known(actual[field])
        ):
            return "Attestation cannot supply an absent delivered field"
        if not isinstance(record, dict) or "value" not in record:
            return "Attestation needs an explicit value and provenance object"
        if any(
            not isinstance(record.get(key), str) or not record[key].strip()
            for key in ("attested_by", "source_ref", "rationale")
        ):
            return "Attestation needs attested_by, source_ref and rationale"
        value = record["value"]
        if value != actual[field] or isinstance(value, bool) != isinstance(actual[field], bool):
            return "Attested value conflicts with delivered field"
    return None


def _result(quantity, reason, **details):
    return {
        "mean": None,
        "sd": None,
        "unit": UNITS[quantity],
        "status": "unsupported",
        "reason": reason,
        "scope": "exact-context released observations only",
        "uncertainty_status": "not_estimated",
        **details,
    }


def _fit(condition, origin, evidence, quantity):
    excluded = []
    contexts = condition.get("measurement_context", {})
    if not isinstance(contexts, dict) or not isinstance(contexts.get(quantity, {}), dict):
        return _result(quantity, "Measurement context must map quantities to context objects")
    context = contexts.get(quantity, {})
    measurement_keys = list(MEASUREMENT_CONTEXT)
    if origin == "physical" and quantity in GRAIN_QUANTITIES:
        measurement_keys += ["feature_definition", "weighting", "sampling_plan"]
    elif origin == "physical" and quantity == "porosity_area_fraction":
        measurement_keys += ["weighting", "sampling_plan"]
    for key in ("feature_definition", "weighting", "sampling_plan"):
        if key in context and key not in measurement_keys:
            measurement_keys.append(key)
    missing = [key for key in CONTEXT if not _known(condition.get(key))]
    missing += [
        "measurement_context." + quantity + "." + key
        for key in measurement_keys
        if not isinstance(context.get(key), str) or not context[key].strip()
    ]
    if missing:
        return _result(quantity, "Required request context is missing", missing_context=missing)
    if quantity == "coarse_number_fraction" and (
        not _number(context.get("coarse_threshold_nm")) or context["coarse_threshold_nm"] <= 0
    ):
        return _result(
            quantity, "Coarse fraction requires an explicit positive coarse_threshold_nm"
        )
    if origin not in {"physical", "synthetic"}:
        return _result(quantity, "Request origin must explicitly be physical or synthetic")
    if any(not _number(condition[key]) for key in NUMERIC_CONTEXT):
        return _result(quantity, "Numeric process context must be finite numbers, not booleans")
    target = condition.get("temperature_c")
    if not _number(target):
        return _result(quantity, "Requested temperature must be finite")
    if condition.get("evidence_origin", origin) != origin:
        return _result(quantity, "Request and evidence origins disagree")
    grouping = condition.get("repeat_grouping")
    if grouping is not None and (
        not isinstance(grouping, dict)
        or grouping.get("method") != "requested_temperature_delivery"
        or not _number(grouping.get("max_temperature_deviation_c"))
        or grouping["max_temperature_deviation_c"] < 0
        or not isinstance(grouping.get("rationale"), str)
        or not grouping["rationale"].strip()
    ):
        return _result(
            quantity, "Repeat grouping needs an explicit method, tolerance and rationale"
        )

    def reject(row, reason):
        excluded.append({"evidence_id": row.get("evidence_id"), "reason": reason})

    # Repeated IDs are safe only when the records are exactly identical. Never
    # choose whichever conflicting record happened to arrive first.
    by_id = defaultdict(list)
    for row in evidence:
        if row.get("quantity") == quantity and not row.get("superseded", False):
            if not _known(row.get("evidence_id")):
                reject(row, "Missing evidence identity")
            else:
                by_id[row["evidence_id"]].append(row)
    candidates = []
    for rows in by_id.values():
        row = rows[0]
        if any(other != row for other in rows[1:]):
            reject(row, "Conflicting duplicate evidence identity")
            continue
        actual = row.get("delivered_conditions") or {}
        eligible_statuses = (
            {"accepted", "conditional_synthetic"} if origin == "synthetic" else {"accepted"}
        )
        quality_review = row.get("quality_review")
        review_accepted = (
            isinstance(quality_review, dict)
            and quality_review.get("decision") == "accepted"
            and all(
                isinstance(quality_review.get(key), str) and quality_review[key].strip()
                for key in ("reviewer", "rationale")
            )
        )
        if review_accepted:
            eligible_statuses.add("derived")
        attestation_error = _attestation_error(actual)
        if quality_review is not None and not review_accepted:
            reject(row, "Explicit quality review rejects the observation or is incomplete")
        elif not row.get("released_at") or row.get("status") not in eligible_statuses:
            reject(row, "Only explicitly released accepted observations are eligible")
        elif row.get("origin") != origin:
            reject(row, "Observation origin differs from request; no provenance transfer")
        elif actual.get("origin", origin) != origin:
            reject(row, "Delivered origin conflicts with request and observation")
        elif any(key in row and row[key] != actual.get(key) for key in CONTEXT):
            reject(row, "Observation and delivered process context conflict")
        elif attestation_error:
            reject(row, attestation_error)
        elif row.get("unit") != UNITS[quantity] or not _number(row.get("value")):
            reject(row, "Missing, nonfinite or wrong-unit observation")
        elif UNITS[quantity] != "1" and row["value"] <= 0:
            reject(row, "Quantity must be positive")
        elif UNITS[quantity] == "1" and not 0 <= row["value"] <= 1:
            reject(row, "Fraction must be between zero and one")
        elif any(
            not _known(actual.get(key))
            or actual[key] != condition[key]
            or (key in NUMERIC_CONTEXT and not _number(actual[key]))
            for key in CONTEXT
        ):
            reject(row, "Different or missing delivered process, lot or geometry context")
        elif any(row.get(key) != context[key] for key in measurement_keys):
            reject(
                row,
                "Different or missing measurement method, population, statistic or feature definition",
            )
        elif quantity == "coarse_number_fraction" and (
            not _number(row.get("coarse_threshold_nm"))
            or row.get("coarse_threshold_nm") != context["coarse_threshold_nm"]
        ):
            reject(row, "Different or missing coarse threshold")
        elif not _number(actual.get("temperature_c")):
            reject(row, "Missing or nonfinite delivered temperature")
        elif any(
            not _known(row.get(key))
            for key in ("specimen_id", "preparation_id", "cycle_id", "delivery_id")
        ):
            reject(row, "Missing specimen, preparation, cycle or delivery identity")
        elif not _known(row.get("measurement_id") or row.get("observation_id")):
            reject(row, "Missing measurement identity independent of evidence wrapper")
        elif row.get("statistical_unit") != "specimen":
            reject(row, "Requires one explicit specimen-level descriptor, not image fields")
        elif quantity in GRAIN_QUANTITIES and row.get("resolved_grain_boundaries") is not True:
            reject(row, "Grain boundaries unresolved")
        else:
            candidates.append(row)

    # New IDs cannot turn repeat reads/images of the same specimen into repeats.
    # Conflicting descriptors require an explicit corrected/aggregated release.
    measurements = defaultdict(list)
    for row in candidates:
        measurements[row.get("measurement_id") or row["observation_id"]].append(row)
    by_specimen = defaultdict(list)
    for rows in measurements.values():
        row = rows[0]
        if any(
            any(
                other.get(key) != row.get(key)
                for key in (
                    "specimen_id",
                    "value",
                    "delivered_conditions",
                    "preparation_id",
                    "cycle_id",
                    "delivery_id",
                )
            )
            for other in rows[1:]
        ):
            for other in rows:
                reject(other, "Conflicting duplicate measurement identity")
            continue
        by_specimen[row["specimen_id"]].append(row)
        for other in rows[1:]:
            reject(other, "Duplicate measurement does not add an independent repeat")
    accepted = []
    identity_keys = ("value", "delivered_conditions", "preparation_id", "cycle_id", "delivery_id")
    for rows in by_specimen.values():
        row = rows[0]
        if any(any(other.get(key) != row.get(key) for key in identity_keys) for other in rows[1:]):
            for other in rows:
                reject(
                    other, "Ambiguous repeated specimen descriptor; release explicit aggregation"
                )
        else:
            accepted.append(row)
            for other in rows[1:]:
                reject(other, "Duplicate specimen descriptor does not add an independent repeat")
    if not accepted:
        return _result(
            quantity, "No comparable released specimen observations", exclusions=excluded
        )

    temperatures = sorted({row["delivered_conditions"]["temperature_c"] for row in accepted})
    domain = [temperatures[0], temperatures[-1]]
    declared = condition.get("temperature_domain_c")
    if declared is not None:
        if (
            not isinstance(declared, (list, tuple))
            or len(declared) != 2
            or not all(_number(x) for x in declared)
            or declared[0] > declared[1]
        ):
            return _result(quantity, "Malformed declared temperature domain", exclusions=excluded)
        domain = [max(domain[0], declared[0]), min(domain[1], declared[1])]
    if not domain[0] <= target <= domain[1]:
        return _result(
            quantity,
            "Outside both-sided observed/declared temperature domain",
            temperature_domain_c=domain,
            exclusions=excluded,
        )

    cells = defaultdict(list)
    delivery_cells = defaultdict(list)
    grouping_exclusions = []
    for row in accepted:
        temperature = row["delivered_conditions"]["temperature_c"]
        cells[temperature].append(row)
        repeat_temperature = temperature
        if grouping is not None:
            repeat_temperature = (row.get("requested_conditions") or {}).get("temperature_c")
            if (
                not _number(repeat_temperature)
                or abs(temperature - repeat_temperature) > grouping["max_temperature_deviation_c"]
            ):
                grouping_exclusions.append(row["evidence_id"])
                continue  # A valid observation remains in the actual-temperature mean fit.
        delivery_cells[(repeat_temperature, row["delivery_id"])].append(row)
    cell_means = {t: sum(r["value"] for r in rows) / len(rows) for t, rows in cells.items()}
    lower = max(t for t in temperatures if t <= target)
    upper = min(t for t in temperatures if t >= target)
    weight = 0 if upper == lower else (target - lower) / (upper - lower)
    mean = (1 - weight) * cell_means[lower] + weight * cell_means[upper]

    # Count dependence across the complete evidence slice, not just each cell.
    preps = Counter(row["preparation_id"] for row in accepted)
    cycles = Counter(row["cycle_id"] for row in accepted)
    residual_ss, residual_df = 0.0, 0
    summaries = []
    for (temperature, delivery_id), rows in sorted(delivery_cells.items()):
        independent = all(
            preps[r["preparation_id"]] == 1 and cycles[r["cycle_id"]] == 1 for r in rows
        )
        n = len(rows)
        cell_mean = sum(r["value"] for r in rows) / n
        variance = (
            sum((r["value"] - cell_mean) ** 2 for r in rows) / (n - 1)
            if independent and n > 1
            else None
        )
        if variance is not None:
            residual_ss += variance * (n - 1)
            residual_df += n - 1
        summaries.append(
            {
                "temperature_c": temperature,
                "delivery_id": delivery_id,
                "n_specimens": n,
                "independent_preparations_and_cycles": independent,
                "mean": cell_mean,
                "observed_individual_sd": math.sqrt(variance) if variance is not None else None,
                "within_delivery_mean_se": math.sqrt(variance / n)
                if variance is not None
                else None,
                "actual_temperature_range_c": [
                    min(r["delivered_conditions"]["temperature_c"] for r in rows),
                    max(r["delivered_conditions"]["temperature_c"] for r in rows),
                ],
            }
        )
    return {
        "mean": mean,
        "sd": None,
        "unit": UNITS[quantity],
        **(
            {"coarse_threshold_nm": context["coarse_threshold_nm"]}
            if quantity == "coarse_number_fraction"
            else {}
        ),
        "status": "conditional_local_descriptive_fit",
        "scope": {
            **{key: condition[key] for key in CONTEXT},
            "origin": origin,
            "measurement_context": context,
            "temperature_domain_c": domain,
            "operator_attestations": [
                {
                    "evidence_id": row["evidence_id"],
                    "fields": {
                        key: dict(record)
                        for key, record in row["delivered_conditions"]["attestations"].items()
                    },
                }
                for row in accepted
                if row["delivered_conditions"].get("attestations")
            ],
        },
        "method": "piecewise_linear_exact_temperature_cell_means",
        "uncertainty_status": "future_specimen_predictive_uncertainty_not_estimated",
        "prediction_target": "new_individual_specimen_in_future_delivery",
        "evidence_ids": [r["evidence_id"] for r in accepted],
        "n_specimens": len(accepted),
        "exclusions": excluded,
        "uncertainty_components": {
            "grouping": grouping or {"method": "exact_actual_temperature_delivery"},
            "grouping_excluded_evidence_ids": grouping_exclusions,
            "scatter_includes_readback_variation": grouping is not None,
            "observed_within_temperature_delivery_individual_sd": math.sqrt(
                residual_ss / residual_df
            )
            if residual_df
            else None,
            "within_temperature_delivery_df": residual_df,
            "temperature_delivery_cells": summaries,
            "between_delivery_sd": None,
            "interpolation_model_error_sd": None,
            "future_individual_predictive_sd": None,
        },
        "limitations": [
            "Same-lot local interpolation is an assumption, not physical validation",
            "Exact temperature cells do not smooth readback jitter or infer nominal setpoints",
            "Optional requested-setpoint repeat scatter includes delivered-temperature variation; it is not deconvolved noise",
            "Reported cell SE describes a within-delivery mean, never a future specimen",
            "Repeat scatter is descriptive; no between-delivery variance or confidence bound is fitted",
            "Pooled residual scatter assumes comparable variance across these cells",
            "Shared preparation or cycle identifiers exclude their entire cell from repeat variance",
            "Selection bias, unrecorded history and measurement error are not identified",
            "No interval or probability of noninferiority is supplied from unknown predictive uncertainty",
            "Grain descriptor does not determine grain-boundary chemistry or magnetic performance",
        ],
    }


def forecast(payload):
    """Forecast each requested specimen using only the supplied released evidence.

    Caller supplies the public campaign evidence snapshot. Release markers are
    eligibility checks, not independent authentication; campaign verifies custody.
    """
    request = payload["request"]
    predictions = []
    for specimen in request["specimens"]:
        condition = dict(specimen["conditions"])
        condition.setdefault("lot_id", request.get("lot_id"))
        contexts = condition.get("measurement_context", {})
        out = {"specimen_id": specimen["specimen_id"]}
        for quantity in UNITS:
            if quantity not in {"density_g_cm3", "grain_size_nm"} and (
                not isinstance(contexts, dict) or quantity not in contexts
            ):
                continue
            if condition.get("origin", request.get("origin")) != request.get("origin"):
                out[quantity] = _result(quantity, "Condition origin conflicts with request origin")
            elif condition["lot_id"] != request.get("lot_id"):
                out[quantity] = _result(quantity, "Specimen lot conflicts with request lot")
            else:
                out[quantity] = _fit(
                    condition, request.get("origin"), payload.get("evidence", []), quantity
                )
        predictions.append(out)
    return {
        "predictions": predictions,
        "model_version": MODEL_VERSION,
        "model_origin": "owner_maintained_exact_context_fitted_model",
    }


def fitted_model_source():
    """Return the same maintained code for isolated campaign model execution."""
    from pathlib import Path

    return Path(__file__).read_text().split("\ndef fitted_model_source():", 1)[0]
